import{_ as p,a0 as o,w as r,s as d,ao as n,I as l,a1 as i,A as a,x as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何即时设置一个静态文件服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何即时设置一个静态文件服务器 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何即时设置一个静态文件服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何即时设置一个静态文件服务器 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20180411 How To Setup Static File Server Instantly","title":"如何即时设置一个静态文件服务器","tag":"201901","desc":""},"relativePath":"201901/20180411 How To Setup Static File Server Instantly.md","filePath":"[post].md"}'),h={name:"201901/20180411 How To Setup Static File Server Instantly.md"};function c(g,e,u,k,b,m){const t=o("Link");return r(),d("div",null,[e[20]||(e[20]=n('<h1 id="如何即时设置一个静态文件服务器" tabindex="-1">如何即时设置一个静态文件服务器 <a class="header-anchor" href="#如何即时设置一个静态文件服务器" aria-label="Permalink to “如何即时设置一个静态文件服务器”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/04/serve-720x340.png" alt=""></p><p>曾经想通过网络共享你的文件或项目，但不知道怎么做？别担心！这里有一个名为 <strong>serve</strong> 的简单实用程序，可以通过网络即时共享你的文件。这个简单的实用程序会立即将你的系统变成一个静态文件服务器，允许你通过网络提供文件。你可以从任何设备访问这些文件，而不用担心它们的操作系统是什么。你所需的只是一个 Web 浏览器。这个实用程序还可以用来服务静态网站。它以前称为 “list” 或 “micri-list”，但现在名称已改为 “serve”（提供），这更适合这个实用程序的目的。</p><h3 id="使用-serve-来设置一个静态文件服务器" tabindex="-1">使用 Serve 来设置一个静态文件服务器 <a class="header-anchor" href="#使用-serve-来设置一个静态文件服务器" aria-label="Permalink to “使用 Serve 来设置一个静态文件服务器”">​</a></h3><p>要安装 serve，首先你需要安装 NodeJS 和 NPM。参考以下链接在 Linux 中安装 NodeJS 和 NPM。</p>',5)),l("ul",null,[l("li",null,[i(t,{href:"https://www.ostechnix.com/install-node-js-linux/"},{default:a(()=>[...e[0]||(e[0]=[s("如何在 Linux 上安装 NodeJS",-1)])]),_:1})])]),e[21]||(e[21]=n('<p>NodeJS 和 NPM 安装完成后，运行以下命令来安装 serve：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ npm install -g serve</span></span></code></pre></div><p>完成！现在是时候 serve 文件或文件夹了。</p><p>使用 serve 的典型语法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ serve [options] &lt;path-to-files-or-folders&gt;</span></span></code></pre></div><h3 id="提供特定文件或文件夹" tabindex="-1">提供特定文件或文件夹 <a class="header-anchor" href="#提供特定文件或文件夹" aria-label="Permalink to “提供特定文件或文件夹”">​</a></h3><p>例如，让我们共享 <code>Documents</code> 目录里的内容。为此，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ serve Documents/</span></span></code></pre></div><p>示例输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/04/serve-1.png" alt=""></p><p>正如你在上图中看到的，给定目录的内容已通过两个 URL 提供网络支持。</p><p>要从本地系统访问内容，你只需打开 Web 浏览器，输入 URL <code>http://localhost:5000/</code>：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/04/serve-2.png" alt=""></p><p>serve 实用程序以简单的布局显示给定目录的内容。你可以下载（右键单击文件并选择“将链接另存为...”）或只在浏览器中查看它们。</p><p>如果想要在浏览器中自动打开本地地址，使用 <code>-o</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ serve -o Documents/</span></span></code></pre></div><p>运行上述命令后，serve 实用程序将自动打开 Web 浏览器并显示共享项的内容。</p><p>同样，要通过网络从远程系统访问共享目录，可以在浏览器地址栏中输入 <code>http://192.168.43.192:5000</code>。用你系统的 IP 替换 192.168.43.192。</p><h3 id="通过不同的端口提供内容" tabindex="-1">通过不同的端口提供内容 <a class="header-anchor" href="#通过不同的端口提供内容" aria-label="Permalink to “通过不同的端口提供内容”">​</a></h3><p>你可能已经注意到，默认情况下，serve 实用程序使用端口 5000。因此，确保防火墙或路由器中允许使用端口 5000。如果由于某种原因被阻止，你可以使用 <code>-p</code> 选项使用不同端口来提供内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ serve -p 1234 Documents/</span></span></code></pre></div><p>上面的命令将通过端口 1234 提供 <code>Documents</code> 目录的内容。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/04/serve-4.png" alt=""></p><p>要提供文件而不是文件夹，只需给它完整的路径，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ serve Documents/Papers/notes.txt</span></span></code></pre></div><p>只要知道路径，网络上的任何用户都可以访问共享目录的内容。</p><h3 id="提供整个-home-目录" tabindex="-1">提供整个 <code>$HOME</code> 目录 <a class="header-anchor" href="#提供整个-home-目录" aria-label="Permalink to “提供整个 $HOME 目录”">​</a></h3><p>打开终端输入</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ serve</span></span></code></pre></div><p>这将通过网络共享整个 <code>$HOME</code> 目录的内容。</p><p>要停止共享，按下 <code>CTRL+C</code>。</p><h3 id="提供选定的文件或文件夹" tabindex="-1">提供选定的文件或文件夹 <a class="header-anchor" href="#提供选定的文件或文件夹" aria-label="Permalink to “提供选定的文件或文件夹”">​</a></h3><p>你可能不想共享所有文件或目录，只想共享其中的一些。你可以使用 <code>-i</code> 选项排除文件或目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ serve -i Downloads/</span></span></code></pre></div><p>以上命令将提供整个文件系统，除了 <code>Downloads</code> 目录。</p><h3 id="仅在本地主机上提供内容" tabindex="-1">仅在本地主机上提供内容 <a class="header-anchor" href="#仅在本地主机上提供内容" aria-label="Permalink to “仅在本地主机上提供内容”">​</a></h3><p>有时，你只想在本地系统而不是整个网络上提供内容。为此，使用 <code>-l</code> 标志，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ serve -l Documents/</span></span></code></pre></div><p>此命令会仅在本地提供 <code>Documents</code> 目录。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/04/serve-3.png" alt=""></p><p>当你在共享服务器上工作时，这可能会很有用。系统中的所有用户都可以访问共享，但远程用户不能。</p><h3 id="使用-ssl-提供内容" tabindex="-1">使用 SSL 提供内容 <a class="header-anchor" href="#使用-ssl-提供内容" aria-label="Permalink to “使用 SSL 提供内容”">​</a></h3><p>由于我们通过本地网络提供内容，因此我们不需要使用 SSL。但是，serve 实用程序可以使用 <code>-ssl</code> 选项来使用 SSL 共享内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ serve --ssl Documents/</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/04/serve-6.png" alt=""></p><p>要通过 Web 浏览器访问共享，输入 <code>https://localhost:5000</code> 或 <code>https://ip:5000</code>。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/04/serve-5-1.png" alt=""></p><h3 id="通过身份验证提供内容" tabindex="-1">通过身份验证提供内容 <a class="header-anchor" href="#通过身份验证提供内容" aria-label="Permalink to “通过身份验证提供内容”">​</a></h3><p>在上面的所有示例中，我们在没有任何身份验证的情况下提供内容，所以网络上的任何人都可以在没有任何身份验证的情况下访问共享内容。你可能会觉得应该使用用户名和密码访问某些内容。</p><p>为此，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ SERVE_USER=ostechnix SERVE_PASSWORD=123456 serve --auth</span></span></code></pre></div><p>现在用户需要输入用户名（即 <code>ostechnix</code>）和密码（<code>123456</code>）来访问共享。（LCTT 译注：123456 是非常不好的密码，仅在实验情况下使用）</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/04/serve-7-1.png" alt=""></p>',53)),l("p",null,[e[2]||(e[2]=s("serve 实用程序还有一些其它功能，例如禁用 ",-1)),i(t,{href:"https://www.ostechnix.com/how-to-compress-and-decompress-files-in-linux/"},{default:a(()=>[...e[1]||(e[1]=[s("Gzip 压缩",-1)])]),_:1}),e[3]||(e[3]=s("，设置 CORS 头以允许来自任河源的请求，防止自动复制地址到剪贴板等。通过以下命令，你可以阅读完整的帮助部分。",-1))]),e[22]||(e[22]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ serve help</span></span></code></pre></div><p>好了，这就是全部了。希望这可以帮助到你。更多好东西要来了，敬请关注！</p><p>共勉！</p><p>资源：</p>',4)),l("ul",null,[l("li",null,[i(t,{href:"https://github.com/zeit/serve"},{default:a(()=>[...e[4]||(e[4]=[s("Serve GitHub 仓库",-1)])]),_:1})])]),e[23]||(e[23]=l("hr",null,null,-1)),l("p",null,[e[6]||(e[6]=s("via: ",-1)),i(t,{href:"https://www.ostechnix.com/how-to-setup-static-file-server-instantly/"},{default:a(()=>[...e[5]||(e[5]=[s("https://www.ostechnix.com/how-to-setup-static-file-server-instantly/",-1)])]),_:1})]),l("p",null,[e[11]||(e[11]=s("作者：",-1)),i(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...e[7]||(e[7]=[s("SK",-1)])]),_:1}),e[12]||(e[12]=s(" 选题：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[8]||(e[8]=[s("lujun9972",-1)])]),_:1}),e[13]||(e[13]=s(" 译者：",-1)),i(t,{href:"https://github.com/MjSeven"},{default:a(()=>[...e[9]||(e[9]=[s("MjSeven",-1)])]),_:1}),e[14]||(e[14]=s(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[s("wxy",-1)])]),_:1})]),l("p",null,[e[17]||(e[17]=s("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[15]||(e[15]=[s("LCTT",-1)])]),_:1}),e[18]||(e[18]=s(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:a(()=>[...e[16]||(e[16]=[s("Linux中国",-1)])]),_:1}),e[19]||(e[19]=s(" 荣誉推出",-1))])])}const x=p(h,[["render",c]]);export{w as __pageData,x as default};
